import{_ as t,o as e,c as r,a2 as p}from"./chunks/framework.CHeM0PsO.js";const C=JSON.parse('{"title":"0. 前言","description":"","frontmatter":{"abstract":"","date":"2022/03/06","date_time":"2022/03/06 21:03:17","file_name":"cpp-coroutines-00-foreword","group":"cpp-coroutines","keywords":"C++ Coroutines","position":101,"tags":"C++|Coroutines ","title":"0. 前言"},"headers":[],"relativePath":"topics/cpp-coroutines/00-foreword.md","filePath":"topics/cpp-coroutines/00-foreword.md","lastUpdated":1785284603000}'),s={name:"topics/cpp-coroutines/00-foreword.md"};function n(a,o,c,i,_,u){return e(),r("div",null,[...o[0]||(o[0]=[p('<p>C++ 20 标准发布之后，协程终于正式成为 C++ 特性当中的一员。</p><p>作为一门本身极其复杂的语言，C++ 秉承着不劝退不开心的原则，将协程的 API 设计得非常复杂。以至于有开发者甚至发出了“这玩意根本就不是给人用的”这样的感叹。</p><p>等等，我们是不是搞错了，C++ 协程的 API 确实不是设计给业务开发者直接使用的。实际上，标准当中给出的 API 足够的灵活，也足够的基础，框架的开发者可以基于这些 API 将过去异步的函数改造成协程风格的版本。</p><p>没错，这就是 C++。</p><p>一门不造轮子就让人不舒服的语言，它总是在用它自己的方式逼着开发者进步。为了帮助大家认识和了解 C++ 协程的设计思路以及基本用法，我计划写几篇文章来介绍一下 C++ 协程的相关特性。</p><p>本人 C++ 水平有限，文章内容的安排将尽可能以介绍特性为主，涉及到的框架实现不建议在生产环境当中直接使用。</p><p>另外，为了方便读者阅读和实验，文章涉及到的所有源码均已上传于 <a href="https://github.com/bennyhuo/CppCoroutines" target="_blank" rel="noreferrer">GitHub: bennyhuo/CppCoroutines</a>。</p><p>相信大家读完这一系列文章之后，也还是不一定会 C++ 协程 ：）</p><blockquote><p><strong>说明</strong>：C++ 23 有望基于协程提供不少有用的支持，例如与异步任务密不可分的 executor、network 等等，不过这些内容我暂时不会在后面的文章当中涉及，等 C++ 23 正式发布之后再做补充。</p></blockquote>',9)])])}const l=t(s,[["render",n]]);export{C as __pageData,l as default};
